import{_ as s,a,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"Kubernetes 可观测性：指标、日志与事件","description":"集中呈现信号分层与旧 EFK 日志参考。","frontmatter":{"title":"Kubernetes 可观测性：指标、日志与事件","description":"集中呈现信号分层与旧 EFK 日志参考。","showdocs":{"topics":[{"id":"kubernetes","title":"Kubernetes","link":"/topics/kubernetes/"},{"id":"observability","title":"日志采集与查询","link":"/topics/observability/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Kubernetes 系统教程","summary":"集中呈现信号分层与旧 EFK 日志参考。","status":"active","related":[{"title":"Kubernetes 操作与命令","link":"/systems/kubernetes/plus/ecosystem/kubernetes-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储","link":"/systems/kubernetes/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · 按 Pod、Service 与端点定位故障至Pod 运行但服务不可达的复盘","link":"/systems/kubernetes/troubleshooting-part-02","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · Kubernetes 排障手册","link":"/systems/kubernetes/troubleshooting-part-01","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes：部署配置、服务身份与持久卷","link":"/systems/kubernetes/plus/practice/application","kind":"实践","scope":"general","audience":"general"}],"prev":{"text":"Kubernetes RBAC 与安全","link":"/systems/kubernetes/plus/subjects/13-security-rbac"},"next":{"text":"Kubernetes 升级与维护","link":"/systems/kubernetes/plus/subjects/16-upgrade-maintenance"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Kubernetes RBAC 与安全","link":"/systems/kubernetes/plus/subjects/13-security-rbac"},"next":{"text":"Kubernetes 升级与维护","link":"/systems/kubernetes/plus/subjects/16-upgrade-maintenance"}},"headers":[],"relativePath":"systems/kubernetes/observability.md","filePath":"systems/kubernetes/observability.md"}'),l={name:"systems/kubernetes/observability.md"};function n(r,e,p,h,d,k){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="kubernetes-可观测性-指标、日志与事件" tabindex="-1">Kubernetes 可观测性：指标、日志与事件 <a class="header-anchor" href="#kubernetes-可观测性-指标、日志与事件" aria-label="Permalink to &quot;Kubernetes 可观测性：指标、日志与事件&quot;">​</a></h1><h2 id="part-1" tabindex="-1">Kubernetes 可观测性 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;Kubernetes 可观测性 {#part-1}&quot;">​</a></h2><h3 id="part-1-可观测性分层" tabindex="-1">可观测性分层 <a class="header-anchor" href="#part-1-可观测性分层" aria-label="Permalink to &quot;可观测性分层 {#part-1-可观测性分层}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>重点信号</th><th>常见来源</th></tr></thead><tbody><tr><td>用户体验</td><td>成功率、延迟、吞吐、业务正确性</td><td>应用指标、网关、Tracing</td></tr><tr><td>工作负载</td><td>Ready、副本、重启、OOM、资源和队列</td><td>kube-state-metrics、kubelet、应用</td></tr><tr><td>数据面</td><td>DNS、Service、丢包、连接、Ingress/Gateway</td><td>CNI、CoreDNS、代理、LB</td></tr><tr><td>节点</td><td>CPU、内存、磁盘、inode、网络、压力</td><td>node exporter、kubelet、OS</td></tr><tr><td>控制面</td><td>API 延迟/错误、etcd、调度、控制器队列</td><td>组件 <code>/metrics</code>、日志</td></tr><tr><td>变更与安全</td><td>谁在何时修改了什么</td><td>API audit、部署事件、GitOps</td></tr></tbody></table><p>先定义用户 SLI/SLO，再建立支撑层告警。只看 CPU 或 Pod Running 无法说明业务正常。</p><h3 id="part-1-指标来源" tabindex="-1">指标来源 <a class="header-anchor" href="#part-1-指标来源" aria-label="Permalink to &quot;指标来源 {#part-1-指标来源}&quot;">​</a></h3><ul><li><strong>Metrics Server</strong> 提供 <code>kubectl top</code> 和 HPA Resource Metrics，通常不是长期监控库。</li><li><strong>kube-state-metrics</strong> 把 API 对象状态转换为 Prometheus 指标，不采集容器实际 CPU。</li><li><strong>kubelet/cAdvisor</strong> 提供节点、Pod 和容器资源指标；可用指标随版本/运行时变化。</li><li><strong>应用和网关</strong> 暴露请求、错误、延迟、队列和业务指标。</li><li><strong>控制面组件</strong> 暴露 <code>/metrics</code>；托管服务可能限制访问并提供云监控替代。</li></ul><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --containers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/apis/metrics.k8s.io/v1beta1/nodes&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.items | length&#39;</span></span></code></pre></div><h3 id="part-1-指标标签与基数" tabindex="-1">指标标签与基数 <a class="header-anchor" href="#part-1-指标标签与基数" aria-label="Permalink to &quot;指标标签与基数 {#part-1-指标标签与基数}&quot;">​</a></h3><p>不要把 user ID、request ID、完整 URL、Pod UID 等无界值放指标标签。高基数会消耗内存、存储和查询资源。建议：</p><ul><li>标签用稳定的 service、namespace、cluster、status class、route template。</li><li>请求 ID 放日志/Trace，不放指标标签。</li><li>记录原始状态码时也提供聚合后的 <code>2xx/4xx/5xx</code>。</li><li>对短命 Job/Pod 调整保留和聚合规则，避免序列持续增长。</li></ul><h3 id="part-1-日志" tabindex="-1">日志 <a class="header-anchor" href="#part-1-日志" aria-label="Permalink to &quot;日志 {#part-1-日志}&quot;">​</a></h3><p>容器写 stdout/stderr，由节点日志代理集中采集。应用日志应：</p><ul><li>结构化输出，字段包含时间、级别、service、trace ID、稳定错误码。</li><li>不记录密码、Token、卡号、个人敏感字段或完整请求体。</li><li>多行堆栈有统一解析规则，避免每行变成独立事件。</li><li>设置采样、速率限制和保留策略，错误风暴不会写满节点磁盘。</li><li>时钟同步，统一 UTC 或明确时区。</li></ul><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-containers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since=15m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timestamps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod/web-abc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --previous</span></span></code></pre></div><p><code>kubectl logs</code> 用于即时诊断；Pod 删除、日志轮转或节点故障后可能不可用。</p><h3 id="part-1-event" tabindex="-1">Event <a class="header-anchor" href="#part-1-event" aria-label="Permalink to &quot;Event {#part-1-event}&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sort-by=.lastTimestamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod/web-abc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --field-selector=type=Warning</span></span></code></pre></div><p>Event 适合解释调度、拉镜像、挂载、探针和驱逐，但会聚合、限流和过期。关键 Event 应被采集或转成指标，仍不能代替审计日志。</p><h3 id="part-1-分布式追踪" tabindex="-1">分布式追踪 <a class="header-anchor" href="#part-1-分布式追踪" aria-label="Permalink to &quot;分布式追踪 {#part-1-分布式追踪}&quot;">​</a></h3><p>使用 OpenTelemetry 等标准传递 trace context，采样策略覆盖错误、慢请求和少量正常流量。Trace 应跨网关、服务、队列消费者和数据库客户端；异步链路需明确 producer/consumer 关联。</p><p>追踪后端同样可能包含敏感参数，Span 属性遵守最小化原则。不要为了追踪在所有请求中记录完整 SQL、Header 或消息体。</p><h3 id="part-1-api-审计" tabindex="-1">API 审计 <a class="header-anchor" href="#part-1-api-审计" aria-label="Permalink to &quot;API 审计 {#part-1-api-审计}&quot;">​</a></h3><p>API Audit 记录请求阶段、身份、verb、资源、响应码等。审计级别 <code>Metadata</code>、<code>Request</code>、<code>RequestResponse</code> 的成本和敏感度逐级增加；Secret、TokenReview 等资源通常不记录正文。</p><p>必须监控审计后端失败与磁盘使用，审计策略变更也纳入审批。托管集群在云审计产品中配置，核对默认是否开启及保留多久。</p><h3 id="part-1-v1-36-组件诊断端点" tabindex="-1">v1.36 组件诊断端点 <a class="header-anchor" href="#part-1-v1-36-组件诊断端点" aria-label="Permalink to &quot;v1.36 组件诊断端点 {#part-1-v1-36-组件诊断端点}&quot;">​</a></h3><p>v1.36 中组件 <code>/statusz</code> 和 <code>/flagz</code> 能力进入 Beta，可显示启动时间、版本和有效启动参数，是否开放取决于 Feature Gate、组件和授权。启动参数可能泄露内部路径或拓扑，只给受控运维身份。</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/version&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/readyz?verbose&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/livez?verbose&#39;</span></span></code></pre></div><p>403 表示当前身份无相应非资源 URL 权限，不要为方便直接授予宽泛 <code>/</code> 或 <code>*</code>。</p><h3 id="part-1-slo-与告警" tabindex="-1">SLO 与告警 <a class="header-anchor" href="#part-1-slo-与告警" aria-label="Permalink to &quot;SLO 与告警 {#part-1-slo-与告警}&quot;">​</a></h3><p>推荐以症状为主、原因为辅：</p><ol><li>页面告警：用户成功率/延迟违反多窗口 Burn Rate、核心服务完全不可用、数据安全风险。</li><li>工单告警：容量趋势、证书临近过期、版本 EOL、备份失败、资源长期浪费。</li><li>诊断信号：Pod 重启、单节点高 CPU 等，只有影响 SLO 或持续异常时升级。</li></ol><p>每条告警包含：影响、集群/命名空间/工作负载、Dashboard、Runbook、最近变更和静默/升级规则。避免为每个 Pod 短暂重启呼叫值班。</p><h3 id="part-1-关键告警建议" tabindex="-1">关键告警建议 <a class="header-anchor" href="#part-1-关键告警建议" aria-label="Permalink to &quot;关键告警建议 {#part-1-关键告警建议}&quot;">​</a></h3><ul><li>Deployment 可用副本不足、StatefulSet 更新卡住、DaemonSet 未就绪。</li><li>CrashLoop/OOM/探针失败持续，Pending 超过调度 SLO。</li><li>API 错误率和延迟、etcd 无 Leader/空间/延迟、调度器队列异常。</li><li>节点 NotReady、Memory/Disk/PID Pressure、磁盘/inode/证书接近阈值。</li><li>CoreDNS 错误/延迟、CNI 地址耗尽、Ingress 5xx、无 EndpointSlice。</li><li>PVC Pending、容量接近满、CSI 操作失败、快照/备份失败。</li><li>HPA 达上限仍过载、指标不可用、节点扩容失败。</li><li>RBAC/准入关键变更、异常 exec、审计流中断。</li></ul><h3 id="part-1-变更关联" tabindex="-1">变更关联 <a class="header-anchor" href="#part-1-变更关联" aria-label="Permalink to &quot;变更关联 {#part-1-变更关联}&quot;">​</a></h3><p>把部署版本、Git SHA、配置版本和变更单作为低基数元数据发送到监控系统。事故时间线同时展示：</p><ul><li>Deployment rollout、ConfigMap/Secret 引用变化。</li><li>节点池、CNI/CSI/Ingress 和控制面升级。</li><li>HPA/副本/流量变化。</li><li>上游依赖与云平台事件。</li></ul><p>可观测性的价值是缩短发现与定位时间；Dashboard 数量不是目标。每季度用演练验证“从告警到根因和恢复”链路。</p><h2 id="part-2" tabindex="-1">Kubernetes EFK 日志组件职责 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Kubernetes EFK 日志组件职责 {#part-2}&quot;">​</a></h2><h3 id="part-2-k8s日志" tabindex="-1">K8s日志 <a class="header-anchor" href="#part-2-k8s日志" aria-label="Permalink to &quot;K8s日志 {#part-2-k8s日志}&quot;">​</a></h3><ul><li>日志记录代理（logging-agent）：日志记录代理用于从容器中获取日志信息，使用Fluentd；<a href="https://www.fluentd.org/" target="_blank" rel="noopener noreferrer">官网</a></li><li>日志记录后台（Logging-Backend）：日志记录后台用于处理日志记录代理推送过来的日志，使用Elasticsearch；<a href="https://www.elastic.co/cn/cloud/?elektra=home&amp;storm=sub1" target="_blank" rel="noopener noreferrer">官网</a></li><li>日志记录展示：日志记录展示用于向用户显示统一的日志信息，使用Kibana<a href="https://www.elastic.co/cn/webinars/getting-started-kibana?elektra=home&amp;storm=sub2" target="_blank" rel="noopener noreferrer">官网</a></li></ul><p><span id="part-2-kubernetes日志采集-efk-md"></span></p>`,43)])])}const u=s(l,[["render",n]]);export{c as __pageData,u as default};
